WITH repeated AS MATERIALIZED (
SELECT i.id item_id,r.id request_id,g.profile_id,min(extract(epoch FROM (r.created_at-o.created_at))/3600.0) hours_since_completion_classification
FROM recommendation_request r JOIN recommendation_served_item i ON i.request_id=r.id JOIN recommendation_profile_projection_generation g ON g.id=i.candidate_provenance->>'projectionId' JOIN recommendation_profile_projection_contribution c ON c.generation_id=g.id AND c.target_media_id=i.target_media_id AND c.kind='qualified_outcome' JOIN recommendation_outcome_revision o ON o.id=c.source_outcome_id AND 'terminal_completed'=ANY(o.reasons)
WHERE r.surface_version='watch-for-you-v1' AND r.created_at>='2026-09-08T01:45:00Z' AND r.created_at<'2026-09-15T01:45:00Z' AND i.candidate_generator='multi-interest-profile' GROUP BY 1,2,3)
SELECT count(*) repeated_completed_cards,count(distinct request_id) affected_requests,count(distinct profile_id) affected_profiles,count(*) FILTER(WHERE hours_since_completion_classification>=0 AND hours_since_completion_classification<=24) within_24h,count(*) FILTER(WHERE hours_since_completion_classification>=0 AND hours_since_completion_classification<=168) within_7d,min(hours_since_completion_classification) minimum_age_hours,max(hours_since_completion_classification) maximum_age_hours FROM repeated;
